{"query":"query CheckRunSteps($ids: [ID!]!) {
  nodes(ids: $ids) {
    ... on CheckRun {
      id
      steps(first: 50) { ...StepsPage }
    }
  }
}

fragment PageInfoFields on PageInfo { hasNextPage endCursor }

fragment StepFields on CheckStep { number name status conclusion secondsToCompletion startedAt completedAt }

fragment StepsPage on CheckStepConnection {
  pageInfo { ...PageInfoFields }
  nodes { ...StepFields }
